@section('page-scripts')
    document.querySelectorAll('[data-opname-count-form]').forEach(form => {
        form.querySelectorAll('[data-opname-row]').forEach(row => {
            const input = row.querySelector('.opname-physical');
            const reason = row.querySelector('.opname-reason');
            const output = row.querySelector('.opname-variance');
            const update = () => {
                const value = input.value === '' ? null : Number(input.value);
                const diff = value === null ? null : value - Number(row.dataset.system);
                output.textContent = diff === null ? '—' : `${diff > 0 ? '+' : ''}${diff.toLocaleString('id-ID')}`;
                reason.required = diff !== null && Math.abs(diff) > 0.0005;
            };
            input.addEventListener('input', update);
        });
    });
@endsection
